const LETTER_DURATION = 0.35; // seconds each letter takes to draw
const LETTER_STAGGER = 0.22; // seconds between each letter starting

/**
 * HandwrittenHero
 * Draws "Utforsk fortiden" one letter at a time, like a pen writing it live,
 * then fills each letter in solid once its stroke completes.
 *
 * Usage: <HandwrittenHero /> — drop it in place of your old <h1>.
 */
export default function HandwrittenHero() {
  const [started, setStarted] = useState(false);

  useEffect(() => {
    // Double requestAnimationFrame guarantees the browser has painted
    // the hidden (dashoffset = length) state at least once before we
    // flip to the drawn state, so the transition always plays.
    let raf1;
    let raf2;
    raf1 = requestAnimationFrame(() => {
      raf2 = requestAnimationFrame(() => {
        setStarted(true);
      });
    });
    return () => {
      cancelAnimationFrame(raf1);
      cancelAnimationFrame(raf2);
    };
  }, []);

  return (
    <svg
      viewBox="0 0 1114 263"
      className="w-full max-w-[90vw] md:max-w-2xl lg:max-w-3xl mx-auto h-auto"
      xmlns="http://www.w3.org/2000/svg"
      aria-label="Utforsk fortiden"
      role="img"
    >
      <g transform="translate(20.00, 21.93)">
        {LETTERS.map(({ d, len }, i) => {
          const delay = i * LETTER_STAGGER;
          return (
            <path
              key={i}
              d={d}
              fill="var(--accent)"
              
              
              strokeLinecap="round"
              strokeLinejoin="round"
              style={{
                strokeDasharray: len,
                strokeDashoffset: started ? 0 : len,
                transition: started
                  ? `stroke-dashoffset ${LETTER_DURATION}s ease-in-out ${delay}s, fill 0.5s ease-in ${
                      delay + LETTER_DURATION
                    }s`
                  : "none",
                  stroke:"var(--accent)",
                  strokeWidth:"1",
                fill: started ? "var(--accent)" : "transparent",
              }}
            />
          );
        })}
      </g>
    </svg>
  );
}